actions.script:
String company=related.userCompanyPartyId?.toString()
if(!company || company!=System.getenv('NASQO_ACCOUNTING_STAGE_COMPANY'))
 throw new IllegalStateException('No source import is enabled for this company')
def helper=ec.resource.script('component://growerp/service/NasqoNativeImport.groovy',null)
result=helper.run(ec,company,related.ownerPartyId?.toString(),sourceSha256,mode)
